$$("nav#nav a").forEach(a=>a.addEventListener("click",()=>{$("#nav").classList.remove("open");$("#burger").setAttribute("aria-expanded",false);$$("#nav .has").forEach(h=>{h.classList.remove("open");$("button",h).setAttribute("aria-expanded",false)})}));
$$("#nav .has>button").forEach(b=>b.onclick=()=>{const o=b.parentElement.classList.toggle("open");b.setAttribute("aria-expanded",o)});
document.addEventListener("click",e=>{if(!e.target.closest||!e.target.closest("#nav .has"))$$("#nav .has.open").forEach(h=>{h.classList.remove("open");$("button",h).setAttribute("aria-expanded",false)})});
let GO=null;
$$("form.srch").forEach(f=>f.onsubmit=e=>{e.preventDefault();SQ=f.elements.q.value;try{sessionStorage.setItem("bb-q",SQ)}catch(x){}if(document.body.dataset.page==="search")render();else if(GO)GO("search.html");else location.href="search.html"});
/* Single-file preview only: window.__PAGES holds every page so links work without a server */
if(window.__PAGES){const go=(href,push)=>{const[f,h]=href.split("#"),pg=window.__PAGES[f||"index.html"];if(!pg)return false;
  if(document.body.dataset.file!==(f||"index.html")){ST.msg=false;document.body.dataset.file=f||"index.html";document.body.dataset.page=pg.page;document.body.dataset.id=pg.id||"";$("main").innerHTML=pg.main;boot()}
  if(h){const e=document.getElementById(h);if(e)e.scrollIntoView()}else scrollTo(0,0);return true};
 GO=go;
 document.addEventListener("click",e=>{const a=e.target.closest&&e.target.closest("a[href]");if(!a)return;const h=a.getAttribute("href");if(/^[a-z-]+\.html(#.*)?$/.test(h)&&go(h))e.preventDefault()})}
boot();
